func TestEnumConversationChannel(t *testing.T) {
	t.Run("NewFromString_sms", func(t *testing.T) {
		t.Parallel()
		val, err := NewConversationChannelFromString("sms")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ConversationChannel("sms"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_mms", func(t *testing.T) {
		t.Parallel()
		val, err := NewConversationChannelFromString("mms")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ConversationChannel("mms"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_rcs", func(t *testing.T) {
		t.Parallel()
		val, err := NewConversationChannelFromString("rcs")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ConversationChannel("rcs"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewConversationChannelFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewConversationChannelFromString("sms")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

